    /** Keys offered to the admin when tagging a toolbox skill. */
    public const TOOLBOX_KEYS = [
        'code', 'terminal', 'database', 'sparkles', 'layers', 'cloud', 'shield',
        'cpu', 'lock', 'git-branch', 'chart', 'box', 'wrench', 'network',
        'server', 'globe', 'zap', 'bot', 'palette', 'flask', 'figma', 'github',
    ];

    public static function has(string $name): bool
    {
        return isset(self::BRAND[$name]) || isset(self::STROKE[$name]);
    }

    public static function render(string $name, string $class = 'icon', ?string $label = null): string
    {
        $a11y = $label === null
            ? ' aria-hidden="true" focusable="false"'
            : ' role="img" aria-label="' . htmlspecialchars($label, ENT_QUOTES) . '"';
        $cls = htmlspecialchars($class, ENT_QUOTES);

        if (isset(self::BRAND[$name])) {
            return '<svg class="' . $cls . '" viewBox="0 0 24 24" fill="currentColor"' . $a11y . '>'
                . '<path d="' . self::BRAND[$name] . '"/></svg>';
        }

        if (!isset(self::STROKE[$name])) {
            return '';
        }

        $body = self::STROKE[$name];
        $inner = str_starts_with($body, '<') ? $body : '<path d="' . $body . '"/>';

        return '<svg class="' . $cls . '" viewBox="0 0 24 24" fill="none" stroke="currentColor"'
            . ' stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"' . $a11y . '>'
            . $inner . '</svg>';
    }
}

